import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

public class TimeSeries_createCopy_TriageGen2Test {

    private TimeSeries series;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        // Adding some dummy data
        series.add(new Second(new java.util.Date(1000L)), 10.0);
        series.add(new Second(new java.util.Date(2000L)), 20.0);
        series.add(new Second(new java.util.Date(3000L)), 30.0);
    }









    @Test
    public void testCreateCopy_EmptyRange() throws CloneNotSupportedException {
        // Note: the code uses 'index <= end', so if start=1, end=0 it throws Exception (handled above)
        // If start=0, end=0, it takes 1 item.
        // To test the logic where no items are added, we check the bounds logic.
        // Since the implementation uses 'for (int index = start; index <= end; index++)',
        // a valid 'start <= end' will always execute at least once.

        TimeSeries copy = series.createCopy(0, 0);
        assertEquals(1, copy.getItemCount());
    }




}

